-- Union Territory Disease Analysis Dashboard
-- Replacement dataset: FY 2021-22 through FY 2025-26 only
-- Categories: All, Public, Private, Urban, Rural
-- Dadra & Nagar Haveli + Daman & Diu combined by summing matching source values.
-- Ladakh is intentionally excluded. Only 7 UT names are included.
-- Source parameter labels are retained exactly (including Outpatient/Inpatient/Emergency prefixes).
-- BACKUP your database before running this script.

USE ut_disease_db;

-- Add category column only if it does not already exist.
SET @category_column_exists = (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
  WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'disease_cases' AND COLUMN_NAME = 'category'
);
SET @category_sql = IF(@category_column_exists = 0,
  'ALTER TABLE disease_cases ADD COLUMN category VARCHAR(20) NOT NULL DEFAULT ''All'' AFTER disease',
  'SELECT 1');
PREPARE category_stmt FROM @category_sql;
EXECUTE category_stmt;
DEALLOCATE PREPARE category_stmt;

-- This project should contain ONLY the five requested financial years.
-- The next statement removes all existing rows from disease_cases.
START TRANSACTION;
DELETE FROM disease_cases;

-- 1,540 source combinations x 5 categories = 7,700 inserted records.
